tool_input.command:
$solverPath = 'C:\Users\Administrator\.dsh\skills\captcha-recognizer\scripts\solve-captcha.mjs'
$createAttempted = $false
try {
  $stamp = Get-Date -Format 'yyyyMMddHHmmssfff'
  $tail = '{0:D5}' -f (Get-Random -Minimum 10000 -Maximum 99999)
  $companyName = 'T2334-' + $stamp
  $uscc = '91' + '320594' + 'T2334' + $tail
  $legalName = '测试联调'
  $passportNo = 'T2334-' + $stamp
  $captchaData = Invoke-RestMethod -Uri 'http://172.27.13.11:8080/code' -Method Get -TimeoutSec 15
  $answerLines = @($captchaData.img | & node $solverPath '-')
  $captchaAnswer = ($answerLines -join '').Trim()
  if ($captchaAnswer -notmatch '^[A-Za-z0-9]+$') { throw 'captcha solve failed before create' }
  $companyInfo = [ordered]@{
    companyType = '01'
    uniformSocialCreditCode = $uscc
    companyName = $companyName
    legalRepresentative = $legalName
    legalPersonCertificateType = '004'
    corporateIdNo = $passportNo
    orgId = 1
    outFlag = '1'
  }
  $backgroundInfo = [ordered]@{ contacts = $legalName }
  $payloadObject = [ordered]@{
    tCyjgInfo = $companyInfo
    tCyjgBgxx = $backgroundInfo
    code = $captchaAnswer
    uuid = $captchaData.uuid
  }
  $payloadText = $payloadObject | ConvertTo-Json -Depth 8 -Compress
  $createAttempted = $true
  $createResponse = Invoke-WebRequest -Uri 'http://172.27.13.11:8080/company/base/createTempAccount' -Method Post -ContentType 'application/json' -Body $payloadText -UseBasicParsing -SkipHttpErrorCheck -TimeoutSec 25
  $createResult = $createResponse.Content | ConvertFrom-Json
  $createCode = [int]$createResult.code
  if ($createCode -ne 200 -or -not $createResult.data.userName -or -not $createResult.data.password) {
    $category = 'other'
    if ([string]$createResult.msg -match '统一社会信用代码已存在|企业名称已存在') { $category = 'duplicate' }
    elseif ([string]$createResult.msg -match '验证码') { $category = 'captcha' }
    elseif ([string]$createResult.msg -match '企业所属机构不存在') { $category = 'org-mapping' }
    'registrationCode={0}; category={1}; no retry performed' -f $createCode, $category
  } else {
    $tempAccount = $createResult.data
    $loginCaptcha = Invoke-RestMethod -Uri 'http://172.27.13.11:8080/code' -Method Get -TimeoutSec 15
    $loginAnswerLines = @($loginCaptcha.img | & node $solverPath '-')
    $loginAnswer = ($loginAnswerLines -join '').Trim()
    if ($loginAnswer -notmatch '^[A-Za-z0-9]+$') {
      'registrationCode=200; loginAttempted=false; recordPersisted=true'
    } else {
      $loginPayloadObject = [ordered]@{
        username = $tempAccount.userName
        password = $tempAccount.password
        code = $loginAnswer
        uuid = $loginCaptcha.uuid
      }
      $loginPayload = $loginPayloadObject | ConvertTo-Json -Depth 5 -Compress
      $loginResponse = Invoke-WebRequest -Uri 'http://172.27.13.11:8080/auth/login' -Method Post -ContentType 'application/json' -Body $loginPayload -UseBasicParsing -SkipHttpErrorCheck -TimeoutSec 25
      $loginResult = $loginResponse.Content | ConvertFrom-Json
      $loginCode = [int]$loginResult.code
      $token = [string]$loginResult.token
      if (-not $token -and $loginResult.data -is [string]) { $token = [string]$loginResult.data }
      if (-not $token -and $loginResult.data.token) { $token = [string]$loginResult.data.token }
      $infoCode = 'not-queried'
      $userType = 'not-queried'
      if ($loginCode -eq 200 -and $token) {
        $infoResponse = Invoke-WebRequest -Uri 'http://172.27.13.11:8080/system/user/getInfo' -Method Get -Headers @{ Authorization = ('Bearer ' + $token) } -UseBasicParsing -SkipHttpErrorCheck -TimeoutSec 15
        $infoResult = $infoResponse.Content | ConvertFrom-Json
        $infoCode = [string]$infoResult.code
        if ($infoResult.user.userType) { $userType = [string]$infoResult.user.userType }
        elseif ($infoResult.data.user.userType) { $userType = [string]$infoResult.data.user.userType }
      }
      'registrationCode=200; loginCode={0}; getInfoCode={1}; userType={2}; syntheticMarker=T2334; recordPersisted=true' -f $loginCode, $infoCode, $userType
    }
  }
} catch {
  if ($createAttempted) { 'registration attempt outcome may be partial or uncertain; do not retry; error type={0}' -f $_.Exception.GetType().Name }
  else { 'stopped before registration write; error type={0}' -f $_.Exception.GetType().Name }
}
